INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES ("もうすぐ、みなさまに\nお会いできるのですね。\n胸が高鳴ってしまいます……\n", "リリ", 321, 2, 1, 1, 40011, 24001, 125801, 0, 1);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES ("初めまして、クリアです♪\nみなさんと一緒に冒険するの\nとっても楽しみにしてます", "クリア", 322, 2, 1, 1, 40011, 24001, 126001, 0, 2);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES ("んーと。\nこれ、あげる。\nはい", "プレシア", 323, 2, 1, 1, 40011, 24001, 126101, 0, 3);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES ("あらためまして……\n【アルターメイデン】の\nギルドマスター、リリと申します", "リリ", 324, 2, 1, 2, 40011, 24001, 125801, 0, 4);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES ("こんにちは、お兄さん♪\n【アルターメイデン】の\nクリアです", "クリア", 325, 2, 1, 2, 40011, 24001, 126001, 0, 5);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES ("お兄。\nきてくれて、うれしい", "プレシア", 326, 2, 1, 2, 40011, 24001, 126101, 0, 6);
